module tb_TopModule;
    logic clk;
    logic reset;
    logic x;
    logic z;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .x(x),
        .z(z)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        x = 0;
        @(posedge clk);
        #1;
        if (z !== 0) begin
            $display("SELFFAIL: Reset state z should be 0, got %b", z);
            $finish;
        end

        reset = 0;
        // Test state 000: x=0 -> 000, z=0
        @(posedge clk);
        #1;
        if (z !== 0) $display("FAIL 000 x=0 z");

        // x=1 -> 001
        x = 1;
        @(posedge clk);
        #1;
        if (z !== 0) $display("FAIL 000->001 z");

        // In state 001: x=0 -> 001, z=0
        x = 0;
        @(posedge clk);
        #1;
        if (z !== 0) $display("FAIL 001 x=0 z");

        // In state 001: x=1 -> 100, z=0
        x = 1;
        @(posedge clk);
        #1;
        if (z !== 0) $display("FAIL 001 x=1 z");

        // In state 100: x=1 -> 100, z=1
        x = 1;
        @(posedge clk);
        #1;
        if (z !== 1) $display("FAIL 100 x=1 z");

        // In state 100: x=0 -> 011, z=1
        x = 0;
        @(posedge clk);
        #1;
        if (z !== 1) $display("FAIL 100->011 z (got z=%b)", z);

        // In state 011: x=0 -> 001, z=1
        x = 0;
        @(posedge clk);
        #1;
        if (z !== 1) $display("FAIL 011 x=0 z");

        // Reset test
        reset = 1;
        @(posedge clk);
        #1;
        if (z !== 0) begin
            $display("SELFFAIL: Reset active z should be 0");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic reset;
    logic x;
    logic z;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .x(x),
        .z(z)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        x = 0;
        @(posedge clk);
        #1;
        if (z !== 0 || uut.state !== 3'b000) begin
            $display("SELFTEST FAIL: Reset failed");
            $finish;
        end

        reset = 0;

        // From 000:
        // x=0 -> 000, z=0
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b000 || z !== 0) begin $display("SELFTEST FAIL: 000->000"); $finish; end

        // x=1 -> 001, z=0
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b001 || z !== 0) begin $display("SELFTEST FAIL: 000->001"); $finish; end

        // From 001:
        // x=0 -> 001, z=0
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b001 || z !== 0) begin $display("SELFTEST FAIL: 001->001"); $finish; end

        // x=1 -> 100, z=0
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b100 || z !== 0) begin $display("SELFTEST FAIL: 001->100"); $finish; end

        // From 100:
        // x=1 -> 100, z=1
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b100 || z !== 1) begin $display("SELFTEST FAIL: 100->100"); $finish; end

        // x=0 -> 011, z=1
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b011 || z !== 1) begin $display("SELFTEST FAIL: 100->011"); $finish; end

        // From 011:
        // x=0 -> 001, z=1
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b001 || z !== 1) begin $display("SELFTEST FAIL: 011->001"); $finish; end

        // Now we are at 001. Go to 100 (x=1), then test state 010.
        // From 001 with x=1 -> 100
        x = 1; @(posedge clk); #1;
        // From 100 with x=0 -> 011
        x = 0; @(posedge clk); #1;
        // From 011 with x=1 -> 010
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b010 || z !== 1) begin $display("SELFTEST FAIL: reaching 010"); $finish; end

        // From 010:
        // x=0 -> 010, z=0
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b010 || z !== 0) begin $display("SELFTEST FAIL: 010->010"); $finish; end

        // x=1 -> 001, z=0
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b001 || z !== 0) begin $display("SELFTEST FAIL: 010->001"); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

