module tb_TopModule;
    logic clk;
    logic reset;
    logic x;
    logic z;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .x(x),
        .z(z)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        reset = 1;
        x = 0;
        @(posedge clk);
        #1;
        if (uut.state !== 3'b000 || z !== 0) begin
            $display("SELFTEST FAIL: Reset failed");
            $finish;
        end

        reset = 0;

        // State 000 -> x=0 -> state 000, z=0
        x = 0;
        #1; // check z while in 000 before clock edge
        if (z !== 0) begin $display("SELFTEST FAIL: 000 z"); $finish; end
        @(posedge clk); #1;
        if (uut.state !== 3'b000) begin $display("SELFTEST FAIL: 000->000 state"); $finish; end

        // State 000 -> x=1 -> next state 001
        x = 1;
        @(posedge clk); #1;
        if (uut.state !== 3'b001) begin $display("SELFTEST FAIL: 000->001 state"); $finish; end
        if (z !== 0) begin $display("SELFTEST FAIL: 001 z"); $finish; end // state 001 has z=0

        // State 001 -> x=0 -> state 001
        x = 0;
        @(posedge clk); #1;
        if (uut.state !== 3'b001) begin $display("SELFTEST FAIL: 001->001 state"); $finish; end

        // State 001 -> x=1 -> state 100
        x = 1;
        @(posedge clk); #1;
        if (uut.state !== 3'b100) begin $display("SELFTEST FAIL: 001->100 state"); $finish; end
        if (z !== 1) begin $display("SELFTEST FAIL: 100 z"); $finish; end // state 100 has z=1

        // State 100 -> x=1 -> state 100
        x = 1;
        @(posedge clk); #1;
        if (uut.state !== 3'b100) begin $display("SELFTEST FAIL: 100->100 state"); $finish; end

        // State 100 -> x=0 -> state 011
        x = 0;
        @(posedge clk); #1;
        if (uut.state !== 3'b011) begin $display("SELFTEST FAIL: 100->011 state"); $finish; end
        if (z !== 1) begin $display("SELFTEST FAIL: 011 z"); $finish; end // state 011 has z=1

        // State 011 -> x=0 -> state 001
        x = 0;
        @(posedge clk); #1;
        if (uut.state !== 3'b001) begin $display("SELFTEST FAIL: 011->001 state"); $finish; end

        // Reach state 010: from 001 (x=1) -> 100, then (x=0) -> 011, then (x=1) -> 010
        x = 1; @(posedge clk); #1; // now in 100
        x = 0; @(posedge clk); #1; // now in 011
        x = 1; @(posedge clk); #1; // now in 010
        if (uut.state !== 3'b010) begin $display("SELFTEST FAIL: reaching 010"); $finish; end
        if (z !== 0) begin $display("SELFTEST FAIL: 010 z"); $finish; end // state 010 has z=0

        // State 010 -> x=0 -> state 010
        x = 0; @(posedge clk); #1;
        if (uut.state !== 3'b010) begin $display("SELFTEST FAIL: 010->010 state"); $finish; end

        // State 010 -> x=1 -> state 001
        x = 1; @(posedge clk); #1;
        if (uut.state !== 3'b001) begin $display("SELFTEST FAIL: 010->001 state"); $finish; end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
